    explain:
      '문제에서 등장하는 세 지표 AIC, BIC, Mallow\'s CP는 모두 오차 제곱합과 함께 모형에 활용한 독립변수(설명변수)의 개수를 고려하여 모형 성능을 수치화한다. 세 지표 모두 작을수록 더 좋은 모형이라는 의미를 갖고, 독립변수의 개수에 따라 페널티가 추가된다. BIC는 베이지안 사후 확률을 근사적으로 계산한 결과에서 나온 지표이다. BIC 수식은 로그 우도와 모델 복잡도에 대한 페널티를 함께 고려해, 사후 확률이 높은 모델을 선호하도록 만들어졌다. 다만 "가중치를 부여"는 모형 평가 지표나 그 개념과 상관이 없는 표현이다. BIC는 변수가 많아질수록 벌점을 부과하며 AIC보다 변수 증가에 더 민감하다.',
