export function chapterName(id) {
  for (const s of SUBJECTS)
    for (const c of s.chapters) if (c.id === id) return c.name;
  return "";
}
export function subjectOfChapter(chapterId) {
  return SUBJECTS.find((s) => s.chapters.some((c) => c.id === chapterId));
}
export function subjectPracticeQuestionIds(subjectId) {
  return Object.keys(QUESTIONS).filter(
    (k) => !QUESTIONS[k].examId && QUESTIONS[k].subjectId === subjectId,
  );
}
